function pinUnpin(){$(".unpin_content").append('<a class="bt_unpin" href="javascript:void(0)" rel="nofollow">Maximixar</a>');$(".bt_unpin").live("click",function(){$(this).parent().wrap('<div class="unpin_container_on"></div>');$(this).html("minimizar").addClass("bt_pin").removeClass("bt_unpin");$(".unpin_container_on").animate({opacity:1},1000)});$(".bt_pin").live("click",function(){$(".unpin_container_on").animate({opacity:0},1000,function(){$(".unpin_content").unwrap()});$(this).html("maximixar").addClass("bt_unpin").removeClass("bt_pin")});$(document).live("keydown",function(a){if(a.which==27){$(".unpin_container_on").animate({opacity:0},1000,function(){$(".unpin_content").unwrap()});$(".bt_pin").html("maximixar").addClass("bt_unpin").removeClass("bt_pin")}})}function modal(b,a,c){function d(){$(".closable").slideUp("normal",function(){$(".closable").parent().fadeOut("normal",function(){$(this).remove()})})}if((a=="")||(a==undefined)||(a==false)){a=""}else{a="on"}if((c=="")||(c==undefined)||(c==false)){c=""}else{c="closable"}$(document).live("keydown",function(f){if(f.which==27){d()}});template_overlay='<div class="modal_overlay"><div class="containerContent '+a+" "+c+'">'+b+"</div></div>";$("body").prepend(template_overlay)};